import{describe,it,expect}from"vitest";import{validateHtmlFiles}from"../../frontend/scripts/pr-health-checker.js";describe("pr-health-checker",()=>{it("should scan repository HTML files and report status",()=>{const e=validateHtmlFiles();expect(e.totalScanned).toBeGreaterThan(0),expect(e.issuesCount).toBeDefined(),expect(Array.isArray(e.issues)).toBe(!0)})});